-- 공용 콘텐츠 이미지 URL을 immutable WebP 객체로 전환한다.
SELECT pg_advisory_xact_lock(hashtext('landit-content-image-webp-migration'));

CREATE TEMP TABLE image_url_remap (
    old_url TEXT PRIMARY KEY,
    new_url TEXT NOT NULL UNIQUE
) ON COMMIT DROP;


CREATE TEMP VIEW current_content_image_urls AS
SELECT thumbnail_url AS image_url
FROM scenario
WHERE thumbnail_url IS NOT NULL AND thumbnail_url <> ''
UNION ALL
SELECT representative_image_url
FROM writing_expression
WHERE representative_image_url IS NOT NULL AND representative_image_url <> ''
UNION ALL
SELECT item.value ->> 'imageUrl'
FROM writing_expression
CROSS JOIN LATERAL jsonb_array_elements(practice_examples_payload) AS item(value)
WHERE item.value ->> 'imageUrl' IS NOT NULL AND item.value ->> 'imageUrl' <> '';

DO $$
DECLARE
    mapping_count INTEGER;
    old_reference_count INTEGER;
    new_reference_count INTEGER;
BEGIN
    SELECT count(*) INTO mapping_count FROM image_url_remap;
    IF mapping_count <> 692 THEN
        RAISE EXCEPTION 'Expected 692 image URL mappings, found %', mapping_count;
    END IF;

    SELECT count(*) INTO old_reference_count
    FROM current_content_image_urls current_url
    JOIN image_url_remap remap ON remap.old_url = current_url.image_url;
    IF old_reference_count <> 692 THEN
        RAISE EXCEPTION 'Expected 692 old image URL references, found %', old_reference_count;
    END IF;

    IF EXISTS (
        SELECT old_url FROM image_url_remap
        EXCEPT
        SELECT image_url FROM current_content_image_urls
    ) THEN
        RAISE EXCEPTION 'One or more expected old image URLs are missing';
    END IF;

    SELECT count(*) INTO new_reference_count
    FROM current_content_image_urls current_url
    JOIN image_url_remap remap ON remap.new_url = current_url.image_url;
    IF new_reference_count <> 0 THEN
        RAISE EXCEPTION 'Expected no new image URL references before migration, found %', new_reference_count;
    END IF;
END $$;

UPDATE scenario target
SET thumbnail_url = remap.new_url,
    updated_at = clock_timestamp()
FROM image_url_remap remap
WHERE target.thumbnail_url = remap.old_url;

UPDATE writing_expression target
SET representative_image_url = remap.new_url,
    updated_at = clock_timestamp()
FROM image_url_remap remap
WHERE target.representative_image_url = remap.old_url;

WITH rebuilt AS (
    SELECT
        expression.id,
        jsonb_agg(
            CASE
                WHEN remap.new_url IS NULL THEN item.value
                ELSE jsonb_set(
                    item.value,
                    '{imageUrl}',
                    to_jsonb(remap.new_url),
                    false
                )
            END
            ORDER BY item.ordinal
        ) AS payload
    FROM writing_expression expression
    CROSS JOIN LATERAL jsonb_array_elements(expression.practice_examples_payload)
        WITH ORDINALITY AS item(value, ordinal)
    LEFT JOIN image_url_remap remap
        ON remap.old_url = item.value ->> 'imageUrl'
    GROUP BY expression.id
    HAVING count(remap.old_url) > 0
)
UPDATE writing_expression target
SET practice_examples_payload = rebuilt.payload,
    updated_at = clock_timestamp()
FROM rebuilt
WHERE target.id = rebuilt.id;

DO $$
DECLARE
    old_reference_count INTEGER;
    new_reference_count INTEGER;
BEGIN
    SELECT count(*) INTO old_reference_count
    FROM current_content_image_urls current_url
    JOIN image_url_remap remap ON remap.old_url = current_url.image_url;
    IF old_reference_count <> 0 THEN
        RAISE EXCEPTION 'Expected no old image URL references after migration, found %', old_reference_count;
    END IF;

    SELECT count(*) INTO new_reference_count
    FROM current_content_image_urls current_url
    JOIN image_url_remap remap ON remap.new_url = current_url.image_url;
    IF new_reference_count <> 692 THEN
        RAISE EXCEPTION 'Expected 692 new image URL references, found %', new_reference_count;
    END IF;

    IF EXISTS (
        SELECT new_url FROM image_url_remap
        EXCEPT
        SELECT image_url FROM current_content_image_urls
    ) THEN
        RAISE EXCEPTION 'One or more new image URLs were not applied';
    END IF;
END $$;
